import axios from "axios";

// Dynamic API base URL configuration
const API = axios.create({
    baseURL: process.env.REACT_APP_API_BASE_URL || "http://localhost:3001", // Use environment variable if available
});

// Helper function for token retrieval
const getAuthToken = () => {
    const token = localStorage.getItem("token");
    if (!token) {
        throw new Error("No authorization token found.");
    }
    return token;
};

// Add Authorization header for protected routes
API.interceptors.request.use((req) => {
    const token = getAuthToken();
    if (token) {
        req.headers.Authorization = `Bearer ${token}`;
    }
    return req;
});

// Authentication APIs
export const loginUser = async ({ username, password }) => {
    try {
        const response = await API.post('/api/login', { username, password });
        // Save the token to localStorage after login
        if (response.data.token) {
            localStorage.setItem("token", response.data.token);
        }
        return response.data; // Assuming response structure: { data: { token, user }}
    } catch (error) {
        console.error("Login failed:", error);
        throw error; // Rethrow the error so you can handle it in the component
    }
};

// Franchise APIs
export const createFranchise = (data) => API.post("/franchises", data);
export const getFranchises = () => API.get("/franchises");  // Corrected route
export const deleteFranchise = (id) => API.delete(`/franchises/${id}`);
export const updateFranchise = (id, data) => API.put(`/franchises/${id}`, data);

// User APIs
export const createUser = (data) => API.post("/users", data);

// Function to get users
export const getUsers = async () => {
    console.log('Fetching users...');
    try {
        const response = await API.get("/users");
        return response.data;
    } catch (error) {
        console.error("Error fetching users:", error);
        throw error;
    }
};

// Function to delete a user by ID
export const deleteUser = async (userId) => {
    try {
        const response = await API.delete(`/users/${userId}`);
        return response.data;
    } catch (error) {
        console.error("Error deleting user:", error);
        throw error;
    }
};

// Function to update a user by ID
export const updateUser = async (userId, userData) => {
    try {
        const response = await API.put(`/users/${userId}`, userData);
        return response.data;
    } catch (error) {
        console.error("Error updating user:", error);
        throw error;
    }
};

// Exam Data APIs for a franchise
export const updateExamData = async (exam) => {
    const { franchiseId, _id, ...examData } = exam;
    if (!franchiseId || !_id) {
        throw new Error('Invalid franchiseId or examId');
    }
    const token = getAuthToken(); // Get token from helper function
    const url = `/franchises/${franchiseId}/exam-data/${_id}`;
    try {
        return await API.put(url, examData, {
            headers: {
                Authorization: `Bearer ${token}`,
            }
        });
    } catch (error) {
        console.error("Error updating exam data:", error);
        throw error;
    }
};

// Get franchises associated with the logged-in user
export const getAssociatedFranchises = async () => {
    try {
        const response = await API.get('/franchises/associated');
        return response.data;
    } catch (error) {
        console.error("Error fetching associated franchises:", error);
        throw error;
    }
};

// API for managing user exam data for a franchise

// Create Exam Data
export const createUserExamData = async (examData) => {
    const { franchiseId } = examData;
    if (!franchiseId) {
        throw new Error('Franchise ID is required');
    }
    const token = getAuthToken(); // Get token from helper function
    try {
        const response = await API.post(
            `/franchises/${franchiseId}/exam-data`,
            examData,
            {
                headers: {
                    Authorization: `Bearer ${token}`,
                },
            }
        );
        return response.data;
    } catch (error) {
        console.error("Error creating exam data:", error);
        throw error;
    }
};

// Delete Exam Data
export const deleteUserExamData = async (franchiseId, examId) => {
    const token = getAuthToken(); // Get token from helper function
    try {
        const response = await API.delete(
            `/franchises/${franchiseId}/exam-data/${examId}`,
            {
                headers: {
                    Authorization: `Bearer ${token}`,
                },
            }
        );
        return response.data;
    } catch (error) {
        console.error("Error deleting exam data:", error);
        throw error;
    }
};

// Example in api.js (logout function)

export const logout = async () => {
    try {
        const response = await fetch('http://localhost:3001/api/logout', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                // Include the JWT token or any necessary headers
            },
        });

        if (!response.ok) {
            throw new Error('Failed to log out');
        }

        const data = await response.json();  // Parse the JSON response
        console.log('Logout response:', data);  // For debugging
        return data.message || 'Logged out successfully';
    } catch (error) {
        console.error('Error logging out:', error);  // Log the error in the console
        throw error;  // Propagate the error to the calling code
    }
};

// Delete exam data
export const deleteExamData = (franchiseId, examId) =>
    API.delete(`/franchises/${franchiseId}/exam-data/${examId}`);
